                int cur_x = x;
                int cur_y = y;
                min_x = std::_cpp_min(cur_x, min_x);
                min_y = std::_cpp_min(cur_y, min_y);
                max_x = std::_cpp_max(max_x, cur_x + 1);
                max_y = std::_cpp_max(max_y, cur_y + 1);
